    { line: 1, reason: 'INVALID_JSON' },
    { line: 2, reason: 'NOT_AN_OBJECT' },
    { line: 3, reason: 'NOT_AN_OBJECT' },
    { line: 4, reason: 'MISSING_OP' },
    { line: 5, reason: 'MISSING_OP' }
  ]);
  assert.equal(r.rows[0].verdict, 'MATCH');
  assert.equal(r.overall, 'NOT_ACCEPTED');
});

